package com.jobtracker.controller;
import com.jobtracker.model.User; import com.jobtracker.repository.UserRepository; import com.jobtracker.security.JwtService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { record Register(@NotBlank String fullName,@Email @NotBlank String email,@Size(min=8)String password){} record Login(@Email @NotBlank String email,@NotBlank String password){} record Response(String token,String email,String fullName){} final UserRepository users; final PasswordEncoder enc; final JwtService jwt; public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;enc=e;jwt=j;} @PostMapping("/register") Response register(@Valid @RequestBody Register r){if(users.findByEmail(r.email().toLowerCase()).isPresent())throw new IllegalArgumentException("Email already registered");User u=users.save(User.builder().fullName(r.fullName()).email(r.email().toLowerCase()).password(enc.encode(r.password())).build());return new Response(jwt.create(u.getEmail()),u.getEmail(),u.getFullName());} @PostMapping("/login") Response login(@Valid @RequestBody Login r){User u=users.findByEmail(r.email().toLowerCase()).orElseThrow(()->new IllegalArgumentException("Invalid credentials"));if(!enc.matches(r.password(),u.getPassword()))throw new IllegalArgumentException("Invalid credentials");return new Response(jwt.create(u.getEmail()),u.getEmail(),u.getFullName());} }